import type { NextConfig } from 'next'
import { withSentryConfig } from '@sentry/nextjs'
import bundleAnalyzer from '@next/bundle-analyzer'

const withBundleAnalyzer = bundleAnalyzer({
  enabled: process.env.ANALYZE === 'true',
})

const nextConfig: NextConfig = {
  output: 'standalone',
  reactStrictMode: true,
  experimental: {
    viewTransition: true,
  },
  turbopack: {
    root: __dirname,
  },
  outputFileTracingRoot: __dirname,
  images: {
    remotePatterns: [
      {
        protocol: 'https',
        hostname: '*.supabase.co',
      },
    ],
  },
  async redirects() {
    // S13 — Navigation consolidation: old sub-routes → tab params on hub pages.
    // All 307 (temporary) — upgrade to 308 permanent once S14 confirms stability.
    return [
      // S18 — Today → Dashboard (permanent). Flipped from the S17 direction after
      // the sidebar label was renamed to "Dashboard" and the route was promoted.
      { source: '/today', destination: '/dashboard', permanent: true },

      // S17 — Commissions + Payroll → /payments tabs (permanent).
      // No /payroll/:path* wildcard — would break /payroll/runs/[id], /payroll/artist-summaries/[id],
      // /payroll/tax-forms/[id] deep links. Top-level redirects only; nested pages remain reachable
      // via their original URLs (linked from within the Payroll tab).
      { source: '/commissions', destination: '/payments?tab=commissions', permanent: true },
      { source: '/payroll', destination: '/payments?tab=payroll', permanent: true },

      // Appointments
      { source: '/waitlist', destination: '/appointments?tab=waitlist', permanent: false },

      // Artists/Team sub-routes
      { source: '/artists/schedules', destination: '/artists?tab=schedules', permanent: false },
      { source: '/guest-artists', destination: '/artists?tab=guest-artists', permanent: false },
      { source: '/settings/team/permissions', destination: '/artists?tab=permissions', permanent: false },

      // Inventory sub-routes
      { source: '/settings/ink-registry', destination: '/inventory?tab=ink-registry', permanent: false },

      // Clients sub-routes
      { source: '/settings/tags', destination: '/clients?tab=tags', permanent: false },
      { source: '/consent-forms', destination: '/clients?tab=consent-forms', permanent: false },
      { source: '/ai-design', destination: '/clients?tab=ai-design', permanent: false },

      // S14 Settings Hub redirects — old flat URLs → new grouped /settings/{group}/{section}
      // All 307 (temporary) — upgrade to 308 after launch confirms stability.
      { source: '/settings/profile',      destination: '/settings/account/profile',      permanent: false },
      { source: '/settings/advanced',     destination: '/settings/account/advanced',     permanent: false },
      { source: '/settings/billing',      destination: '/settings/subscription/billing', permanent: false },
      { source: '/settings/services',     destination: '/settings/studio/services',      permanent: false },
      { source: '/settings/branding',     destination: '/settings/studio/branding',      permanent: false },
      { source: '/settings/booking-page', destination: '/settings/studio/booking-page',  permanent: false },
      { source: '/settings/policies',     destination: '/settings/studio/policies',      permanent: false },
      { source: '/settings/team',         destination: '/settings/team/members',         permanent: false },
      { source: '/settings/locations',    destination: '/locations',                     permanent: false },
      // NOTE: /settings/team/permissions — S13 already redirects to /artists?tab=permissions (S13 wins).
      // NOTE: /settings/ink-registry — S13 redirects to /inventory?tab=ink-registry.
      //   /settings/studio/ink-registry is accessible via sidebar nav directly.
      // NOTE: /settings root → handled by app/(app)/settings/page.tsx redirect().
    ]
  },

  async headers() {
    // Content-Security-Policy (QA #15 — OWASP A05)
    // Start strict; add per-vendor hashes in subsequent sprints.
    // 'unsafe-inline' is limited to styles to support Tailwind class injection.
    // Sentry tunnel goes to /monitoring (same origin).
    // Next.js 16 RSC inlines bootstrap/hydration scripts — requires 'unsafe-inline' on script-src.
    // 'unsafe-eval' is required for React dev-mode; keeps working in prod but can be dropped via nonce later.
    // Blob: scheme needed for workers (FullCalendar + Sentry tunnel).
    const csp = [
      "default-src 'self'",
      "script-src 'self' 'unsafe-inline' 'unsafe-eval' blob:",
      "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
      "font-src 'self' data: https://fonts.gstatic.com",
      "img-src 'self' data: blob: https://*.supabase.co https://*.railway.app",
      "connect-src 'self' https://*.supabase.co https://*.sentry.io wss://*.supabase.co https://app.posthog.com https://*.railway.app",
      "worker-src 'self' blob:",
      "frame-ancestors 'none'",
      "base-uri 'self'",
      "form-action 'self'",
      "object-src 'none'",
    ].join('; ')

    return [
      {
        source: '/:path*',
        headers: [
          {
            key: 'Strict-Transport-Security',
            value: 'max-age=63072000; includeSubDomains; preload',
          },
          { key: 'X-Frame-Options', value: 'DENY' },
          { key: 'X-Content-Type-Options', value: 'nosniff' },
          { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
          { key: 'Content-Security-Policy', value: csp },
          { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=()' },
        ],
      },
    ]
  },
  typescript: {
    ignoreBuildErrors: false,
  },
}

export default withSentryConfig(
  withBundleAnalyzer(nextConfig),
  {
    // Sentry organization + project must be set in CI env via SENTRY_ORG / SENTRY_PROJECT
    silent: true,
    sourcemaps: {
      // Hide source maps from client bundles — they upload to Sentry only
      disable: false,
    },
    widenClientFileUpload: true,
    tunnelRoute: '/monitoring',
    // Disable Sentry telemetry
    telemetry: false,
  },
)

import type { Metadata } from 'next'
import { Inter, Instrument_Serif, JetBrains_Mono } from 'next/font/google'
import { Toaster } from 'sonner'
import { ThemeProvider } from 'next-themes'
import { TooltipProvider } from '@/components/ui/tooltip'
import { QueryProvider } from '@/components/providers/QueryProvider'
import { WebVitalsReporter } from '@/components/providers/WebVitalsReporter'
import './globals.css'

const inter = Inter({
  variable: '--font-sans',
  subsets: ['latin'],
  weight: ['400', '500', '600', '700', '800'],
})

const instrumentSerif = Instrument_Serif({
  variable: '--font-serif',
  subsets: ['latin'],
  weight: ['400'],
  style: ['normal', 'italic'],
})

const jetbrainsMono = JetBrains_Mono({
  variable: '--font-mono',
  subsets: ['latin'],
})

export const metadata: Metadata = {
  title: {
    default: 'InkOS — Tattoo Studio OS',
    template: '%s | InkOS',
  },
  description: 'The operating system for modern tattoo studios.',
  robots: {
    index: false,
    follow: false,
  },
}

// Sprint 10 B8: viewportFit=cover enables env(safe-area-inset-*) on iOS notch devices
export const viewport = {
  viewportFit: 'cover' as const,
}

interface RootLayoutProps {
  children: React.ReactNode
}

export default function RootLayout({ children }: RootLayoutProps) {
  return (
    <html
      lang="en"
      suppressHydrationWarning
      className={`${inter.variable} ${instrumentSerif.variable} ${jetbrainsMono.variable}`}
    >
      <body className="bg-background text-foreground antialiased" suppressHydrationWarning>
        {/* Skip navigation link — hidden until focused, satisfies WCAG 2.4.1 */}
        <a
          href="#main-content"
          className="sr-only focus:not-sr-only focus:fixed focus:top-4 focus:left-4 focus:z-[200] focus:rounded-lg focus:bg-primary focus:px-4 focus:py-2 focus:text-sm focus:font-semibold focus:text-primary-foreground focus:shadow-overlay focus:outline-none"
        >
          Skip to main content
        </a>
        <ThemeProvider
          attribute="class"
          defaultTheme="light"
          disableTransitionOnChange
        >
          <QueryProvider>
            <TooltipProvider>
              {children}
            </TooltipProvider>
          </QueryProvider>
          <WebVitalsReporter />
          <Toaster
            position="top-right"
            richColors
            closeButton
            duration={4000}
            toastOptions={{
              classNames: {
                toast: 'rounded-xl backdrop-blur-sm',
                title: 'font-semibold',
                description: 'text-muted-foreground',
              },
            }}
          />
        </ThemeProvider>
      </body>
    </html>
  )
}

