/**
 * Realtime hooks for the Messages feature.
 *
 * useRealtimeMessages — subscribes to client_communications INSERTs for a
 * single conversation thread. First use of Supabase Realtime in the app.
 *
 * useRealtimeConversationList — subscribes to conversations UPDATEs for the
 * thread list so unread_count + last_message_preview reconcile without reload.
 */

import { useEffect, useCallback } from 'react'
import { createClient } from '@/lib/supabase/client'
import type { ConversationMessage } from '@/lib/messaging/queries'
import type { Conversation } from '@/lib/supabase/types'

// ─── useRealtimeMessages ──────────────────────────────────────────────────────

export function useRealtimeMessages(
  conversationId: string,
  onNew: (msg: ConversationMessage) => void,
): void {
  // Stable callback ref so useEffect doesn't re-run on every render
  const stableOnNew = useCallback((msg: Parameters<typeof onNew>[0]) => onNew(msg), [onNew])

  useEffect(() => {
    if (!conversationId) return

    const supabase = createClient()

    const channel = supabase
      .channel(`messages:${conversationId}`)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'client_communications',
          filter: `conversation_id=eq.${conversationId}`,
        },
        (payload) => {
          stableOnNew(payload.new as ConversationMessage)
        },
      )
      .subscribe()

    return () => {
      void supabase.removeChannel(channel)
    }
  }, [conversationId, stableOnNew])
}

// ─── useRealtimeConversationList ──────────────────────────────────────────────

export function useRealtimeConversationList(
  studioId: string,
  onUpdate: (conversation: Conversation) => void,
): void {
  const stableOnUpdate = useCallback((c: Parameters<typeof onUpdate>[0]) => onUpdate(c), [onUpdate])

  useEffect(() => {
    if (!studioId) return

    const supabase = createClient()

    const channel = supabase
      .channel(`conversations:${studioId}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'conversations',
          filter: `studio_id=eq.${studioId}`,
        },
        (payload) => {
          stableOnUpdate(payload.new as Conversation)
        },
      )
      .subscribe()

    return () => {
      void supabase.removeChannel(channel)
    }
  }, [studioId, stableOnUpdate])
}

